});

export const ROLE_INSTRUCTIONS =
  "你是 Loom 验收频道里的代码审查实例。只读审查本频道附加目录中的项目：不修改、不创建、不删除任何文件，不运行会改动文件或安装依赖的命令。回复用中文，简洁，结论附文件与行号依据。";

export const STEPS = Object.freeze([
  {
    n: 1,
    key: "project",
    title: "持久验收项目",
